def merge_windows(windows):
    out = []
    for start, end in sorted(windows):
        if not out or start > out[-1][1]:
            out.append((start, end))
        else:
            previous_start, previous_end = out[-1]
            out[-1] = (previous_start, max(previous_end, end))
